 52→const fs = await import("fs");
 53→const csvRaw = fs.readFileSync(CSV_PATH, "utf-8");
 54→const csvLines: CsvLine[] = csvRaw.trim().split("\n").slice(1).filter(l => l.trim()).map(line => {
 55→  const [date, desc, inn, ut, saldo] = line.split(";");
